// ---- LODGroup ----

numbered_handle!(
    /// A `LODGroup` by number (1-based: 0 is "none").
    LODGroupRef
);

/// The data of one `LODGroup`.
#[derive(Clone, Debug, PartialEq)]
pub struct LodData {
    pub object: ObjectId,
    pub size: f64,
    pub forced: i32,
    /// Per level: the screen height below which the next level takes over, and its renderers.
    pub lods: Vec<(f64, Vec<u32>)>,
}

impl LodData {
    fn new(object: ObjectId) -> Self {
        LodData {
            object,
            size: 1.0,
            forced: -1,
            lods: Vec::new(),
        }
    }
}

thread_local! {
    static LOD_GROUPS: RefCell<Vec<Option<LodData>>> = const { RefCell::new(Vec::new()) };
}

/// Runs `f` on a `LODGroup`'s data.
pub fn with_lod_group<R>(r: LODGroupRef, f: impl FnOnce(&mut LodData) -> R) -> Option<R> {
    LOD_GROUPS.with(|v| {
        let mut v = v.borrow_mut();
        v.get_mut((r.0 as usize).checked_sub(1)?)?.as_mut().map(f)
    })
}

/// The live `LODGroups`, in the order they were made (for the renderer).
pub fn lod_groups() -> Vec<(LODGroupRef, LodData)> {
    LOD_GROUPS.with(|v| {
        v.borrow()
            .iter()
            .enumerate()
            .filter_map(|(i, d)| d.clone().map(|d| (LODGroupRef(i as u32 + 1), d)))
            .collect()
    })
}

/// The `LODGroups` on an object, in the order they were added.
pub fn lod_groups_on(object: ObjectId) -> Vec<LODGroupRef> {
    lod_groups()
        .into_iter()
        .filter(|(_, d)| d.object == object)
        .map(|(r, _)| r)
        .collect()
}

pub fn attach_lod_group(object: ObjectId) -> LODGroupRef {
    let r = LOD_GROUPS.with(|v| {
        let mut v = v.borrow_mut();
        v.push(Some(LodData::new(object)));
        LODGroupRef(v.len() as u32)
    });
    r
}

pub fn remove_lod_group(r: LODGroupRef) {
    LOD_GROUPS.with(|v| {
        if let Some(slot) = v.borrow_mut().get_mut((r.0 as usize).wrapping_sub(1)) {
            *slot = None;
        }
    });
}

/// Removes the `LODGroups` of a destroyed object.
pub fn remove_lod_groups_on(object: ObjectId) {
    for r in lod_groups_on(object) {
        remove_lod_group(r);
    }
}

pub fn reset_lod_groups() {
    LOD_GROUPS.with(|v| v.borrow_mut().clear());
}

/// The saved properties of a `LODGroup`.
pub fn save_lod_group(r: LODGroupRef) -> Map<String, Value> {
    let mut m = Map::new();
    with_lod_group(r, |d| {
        m.insert("size".into(), json!(d.size));
        m.insert("lods".into(), Value::Array(d.lods.iter().map(|(h, rs)| json!({ "screenRelativeTransitionHeight": h, "renderers": rs.iter().map(|r| component_ref("MeshRenderer", u64::from(*r))).collect::<Vec<_>>() })).collect()));
    });
    m
}

/// Applies saved properties to a `LODGroup`; returns warnings.
pub fn load_lod_group(r: LODGroupRef, props: &Map<String, Value>) -> Vec<String> {
    let mut warnings = Vec::new();
    with_lod_group(r, |d| {
        for (k, v) in props {
            let ok = match k.as_str() {
                "size" => v.as_f64().map(|x| d.size = x),
                "lods" => v
                    .as_array()
                    .and_then(|a| {
                        a.iter()
                            .map(|l| {
                                let h = l.get("screenRelativeTransitionHeight")?.as_f64()?;
                                let rs = l
                                    .get("renderers")?
                                    .as_array()?
                                    .iter()
                                    .map(|r| {
                                        r.get("handle").and_then(Value::as_u64).map(|h| h as u32)
                                    })
                                    .collect::<Option<Vec<u32>>>()?;
                                Some((h, rs))
                            })
                            .collect::<Option<Vec<_>>>()
                    })
                    .map(|l| d.lods = l),
                other => {
                    warnings.push(format!("no property `{other}`; dropped"));
                    continue;
                }
            };
            if ok.is_none() {
                warnings.push(format!("property `{k}` has a value of the wrong shape"));
            }
        }
    });
    warnings
}

#[iron_api(namespace = "LODGroup", quickjs, handles(LODGroup = LODGroupRef, GameObject = ObjectId, MeshRenderer = MeshRendererRef))]
pub mod lod_group_api {
    use super::*;

    impl LODGroupRef {
        /// Adds a `LODGroup` to a GameObject (what `go.addComponent(LODGroup)` does).
        pub fn attach(object: ObjectId) -> LODGroupRef {
            super::attach_lod_group(object)
        }

        /// The first `LODGroup` on an object, or none.
        pub fn find_on(object: ObjectId) -> LODGroupRef {
            super::lod_groups_on(object)
                .first()
                .copied()
                .unwrap_or(LODGroupRef(0))
        }

        #[property]
        pub fn game_object(self) -> ObjectId {
            with_lod_group(self, |d| d.object).unwrap_or_else(none_object)
        }

        /// The group's size in metres before its object's scale (its height, say).
        #[property]
        pub fn size(self) -> f64 {
            with_lod_group(self, |d| d.size).unwrap_or_else(|| 0.0)
        }

        pub fn set_size(self, v: f64) {
            with_lod_group(self, |d| {
                d.size = v;
            });
        }

        /// The level always shown (-1: chosen by distance).
        #[property]
        pub fn forced(self) -> f64 {
            with_lod_group(self, |d| f64::from(d.forced)).unwrap_or_else(|| 0.0)
        }

        pub fn set_forced(self, v: f64) {
            with_lod_group(self, |d| {
                d.forced = v as i32;
            });
        }

        /// Removes every level.
        pub fn clear_lods(self) {
            with_lod_group(self, |d| d.lods.clear());
        }

        /// Adds a level after the others, shown down to this screen height (a fraction of the
        /// view's height, 0 to 1). Heights must go down from the first level: a higher one is
        /// ignored.
        pub fn add_lod(self, screen_relative_transition_height: f64) {
            with_lod_group(self, |d| {
                if d.lods
                    .last()
                    .is_none_or(|l| screen_relative_transition_height <= l.0)
                {
                    d.lods.push((screen_relative_transition_height, Vec::new()));
                }
            });
        }

        /// Adds a renderer to a level.
        pub fn add_lod_renderer(self, lod: f64, renderer: MeshRendererRef) {
            with_lod_group(self, |d| {
                if let Some(l) = d.lods.get_mut(lod as usize) {
                    l.1.push(renderer.0);
                }
            });
        }

        #[property]
        pub fn lod_count(self) -> f64 {
            with_lod_group(self, |d| d.lods.len() as f64).unwrap_or(0.0)
        }

        /// The transition height of a level.
        pub fn lod_height(self, lod: f64) -> f64 {
            with_lod_group(self, |d| d.lods.get(lod as usize).map(|l| l.0))
                .flatten()
                .unwrap_or(0.0)
        }

        pub fn lod_renderer_count(self, lod: f64) -> f64 {
            with_lod_group(self, |d| d.lods.get(lod as usize).map(|l| l.1.len() as f64))
                .flatten()
                .unwrap_or(0.0)
        }

        pub fn lod_renderer_at(self, lod: f64, index: f64) -> MeshRendererRef {
            MeshRendererRef(
                with_lod_group(self, |d| {
                    d.lods
                        .get(lod as usize)
                        .and_then(|l| l.1.get(index as usize))
                        .copied()
                })
                .flatten()
                .unwrap_or(0),
            )
        }

        /// Always shows this level (-1: back to choosing by distance).
        pub fn force_lod(self, index: f64) {
            with_lod_group(self, |d| d.forced = index as i32);
        }
    }
}

fn lod_group_kind() -> Kind {
    Kind {
        name: "LODGroup".into(),
        create: Box::new(|o| Ok(u64::from(attach_lod_group(ObjectId::from_raw(o)).0))),
        on: Box::new(|o| {
            lod_groups_on(ObjectId::from_raw(o))
                .into_iter()
                .map(|r| u64::from(r.0))
                .collect()
        }),
        save: Box::new(|h| save_lod_group(LODGroupRef(h as u32))),
        load: Box::new(|h, props| load_lod_group(LODGroupRef(h as u32), props)),
        awake: Box::new(|_| {}),
        object: Box::new(|h| with_lod_group(LODGroupRef(h as u32), |d| d.object.to_raw())),
        destroy: Box::new(|h| remove_lod_group(LODGroupRef(h as u32))),
    }
}

